%[text] # BEV System Model - Simulation Case
modelName = "BEV_system_model";
load_system(modelName)
BEV_useThermal %[output:76d911b9]
VehSpdRef_loadCase_SimpleDrivePattern( ... %[output:group:7f89daa4] %[output:8460e3b6]
  ModelName = modelName, ... %[output:8460e3b6]
  TargetSubsystemPath = "/Controller & Environment/Vehicle speed reference") %[output:group:7f89daa4] %[output:8460e3b6]
simOut = sim(modelName);
simData = extractTimetable(simOut.logsout);
fig = BEV_ResultsCompactPlot(SimData = simData); %[output:3a1d2667]
